import { Router, type Request, type Response } from 'express';
import { RuntimeAdmission } from '../services/RuntimeAdmission';
import { classifyRuntimeActivity } from '../services/runtimeActivity';
import type { AgentVariantsOrchestrator } from '../agent-variants';
import type { SessionBridgeService } from '../services/SessionBridgeService';
import type { InlineStartTracker } from './inlineStartTracker';
import { RIVET_VERSION } from '../config/telemetry';
import { isLoopbackAddress } from '../utils/loopback';
import { isQueueAccessAuthorized } from '../utils/queueAccess';
import { readRuntimeInterruptions } from '../cli/runtimeInterruption';

export type CreateCliRouterOptions = {
  bridge: SessionBridgeService;
  orchestrator?: AgentVariantsOrchestrator;
  rivetPort: number;
  queueAccessToken?: string | null;
  onShutdown?: () => void;
  beforeUpgrade?: () => void;
  admission?: RuntimeAdmission;
  restartArgs?: string[];
  inlineStart?: Pick<InlineStartTracker, 'isStarting'>;
};

const rejectNonLocalRequest = (req: Request, res: Response): boolean => {
  if (isLoopbackAddress(req.socket.remoteAddress)) return false;
  res.status(403).json({
    error: 'CLI control routes are only accepted from loopback clients.',
    reason: 'loopback_required',
  });
  return true;
};

export const createCliRouter = (options: CreateCliRouterOptions): Router => {
  const { bridge, orchestrator, rivetPort, queueAccessToken } = options;
  const router = Router();
  const admission = options.admission ?? new RuntimeAdmission(RIVET_VERSION);

  const rejectUnauthorized = (req: Request, res: Response): boolean => {
    if (rejectNonLocalRequest(req, res)) return true;
    if (
      !isQueueAccessAuthorized({
        queueAccessToken,
        getHeader: (name) => req.header(name),
      })
    ) {
      res.status(403).json({
        error: 'Queue access denied',
        reason: 'queue_token_required',
      });
      return true;
    }
    return false;
  };

  const readStatus = () => {
    const runtimeInfo = bridge.getSessionRuntimeInfo();
    const activeRun = bridge.getActiveRunCorrelation();
    const projectPath = bridge.getProjectPath();
    return {
      session: {
        isActive: bridge.isActive(),
        sessionId: bridge.getSessionId(),
        projectPath: bridge.getProjectPath(),
        status: bridge.getStatus(),
        roundsCompleted: bridge.getRoundsCompleted(),
        initiator: runtimeInfo.sessionInitiator,
        resolvedRunner: runtimeInfo.resolvedRunner,
        runnerMismatches: runtimeInfo.runnerMismatches,
      },
      queue: {
        apply: bridge.getChannelDepth('apply'),
        variant: bridge.getChannelDepth('variant'),
        queued: bridge.getQueuedBatchMetadata(),
        leases: bridge.getActiveLeaseMetadata(),
      },
      activeRun,
      settledRequestIds: bridge.getSettledRequestIds(),
      variants: {
        ...(orchestrator?.buildActiveSnapshot() ?? { active: false }),
        starting: options.inlineStart?.isStarting() ?? false,
      },
      devServerHealth: bridge.getDevServerHealth(),
      rivetPort,
      rivetVersion: RIVET_VERSION,
      upgrade: admission.status(),
      runtimeInterruptions: projectPath
        ? readRuntimeInterruptions(projectPath)
        : [],
    };
  };

  router.get('/status', (req, res) => {
    if (rejectUnauthorized(req, res)) return;
    res.json(readStatus());
  });

  const retire = async (req: Request, res: Response) => {
    if (rejectUnauthorized(req, res)) return;
    if (req.path === '/upgrade') {
      const clientVersion: unknown = req.body?.clientVersion;
      if (
        typeof clientVersion !== 'string' ||
        !/^\d+\.\d+\.\d+(?:-[\w.-]+)?$/.test(clientVersion)
      ) {
        res.status(400).json({ error: 'A valid clientVersion is required.' });
        return;
      }
      admission.observeClient(clientVersion);
    }
    if (!options.onShutdown) {
      res.status(409).json({
        error:
          'This server is host-managed; stop it from the agent that opened it.',
        reason: 'host_managed_session',
      });
      return;
    }
    if (req.path === '/shutdown') {
      admission.beginShutdown();
      res.json({ stopping: true, upgrade: admission.status() });
      setImmediate(() => options.onShutdown?.());
      return;
    }
    const isIdleRequired = req.body?.requireIdle === true;
    const activity = classifyRuntimeActivity(readStatus());
    if (!admission.beginRetirement(activity, !isIdleRequired)) {
      if (isIdleRequired) {
        res.status(409).json({
          reason: 'active_work',
          error:
            'Rivet left the server running because it has active work or is already restarting.',
          upgrade: admission.status(),
        });
        return;
      }
      res.status(409).json({
        reason: 'server_retiring',
        error:
          'Rivet is already restarting. Retry after the runtime handoff completes.',
        upgrade: admission.status(),
      });
      return;
    }
    try {
      if (
        orchestrator &&
        !(await orchestrator.isHistoryDurableForRestart(true))
      ) {
        admission.cancelRetirement();
        res.status(409).json({
          reason: 'history_not_durable',
          error:
            'Rivet could not verify that all completed directions are saved. The server was left running. Inspect the server log and retry after history is saved.',
          upgrade: admission.status(),
        });
        return;
      }
    } catch {
      admission.cancelRetirement();
      res.status(409).json({
        reason: 'history_not_durable',
        error:
          'Could not verify saved directions. The server was left running.',
        upgrade: admission.status(),
      });
      return;
    }
    options.beforeUpgrade?.();
    res.json({
      stopping: true,
      restartArgs: options.restartArgs,
      upgrade: admission.status(),
    });
    setImmediate(() => options.onShutdown?.());
  };
  router.post('/upgrade', retire);
  router.post('/shutdown', retire);

  return router;
};
